import {installExtensions} from './extensions.js';
import {GraphCanvas,colors,glyphs} from './canvas.js';
import {compatible,adapterPath,analyze,arrange} from './graph-core.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=p=>p+crypto.randomUUID().replaceAll('-','');
const bytes=n=>n>=1024**3?(n/1024**3).toFixed(2)+' GiB':n>=1024**2?(n/1024**2).toFixed(1)+' MiB':n>=1024?(n/1024).toFixed(1)+' KiB':n+' B';
const duration=n=>n>=3600?(n/3600).toFixed(2)+' h':n>=60?(n/60).toFixed(1)+' min':Math.round(n)+' s';
const clone=x=>structuredClone(x);
const state={user:null,csrf:null,nodes:[],templates:[],defs:new Map(),graph:{name:'Untitled pipeline',nodes:[],edges:[]},graphId:null,revision:0,selected:null,library:'all',category:'All',bottom:'execution',assets:[],public:[],scans:[],transfers:[],issues:[],check:null,run:null,attempts:[],outputs:[],logs:[],statuses:new Map(),settings:{},history:[],future:[],version:0,workerReplies:new Map(),source:null,wire:null,saveTimer:null,savePromise:Promise.resolve(),lastWorker:0};
let toastTimer,modalAbort,refreshTimer,logRenderTimer,assetSearchTimer;
async function api(path,options={}){const headers={'X-NGS-Client':'studio',...(options.headers||{})};if(state.csrf)headers['X-CSRF-Token']=state.csrf;if(options.body&&!(options.body instanceof File)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}const r=await fetch('/api'+path,{...options,headers,credentials:'same-origin'});let value;try{value=await r.json();}catch{value={detail:{message:await r.text().catch(()=>r.statusText)}};}if(!r.ok){if(r.status===401)showAuth(false);const detail=value.detail;const e=new Error(typeof detail==='string'?detail:detail?.message||detail?.issues?.[0]?.message||r.statusText);e.detail=detail;e.status=r.status;throw e;}return value;}
function toast(message,error=false){$('#toast').textContent=message;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,error?6500:3500);}
const guarded=fn=>async(...args)=>{try{return await fn(...args);}catch(e){toast(e.message,true);console.error(e.message);}};
function openModal(title,html,eyebrow='WORKSPACE'){modalAbort?.abort();modalAbort=new AbortController();$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();return $('#modalBody');}
function modalClick(selector,fn){$('#modalBody').querySelectorAll(selector).forEach(el=>el.addEventListener('click',guarded(e=>fn(e,el)),{signal:modalAbort.signal}));}
function closeModal(){$('#modal').close();modalAbort?.abort();}
$('#closeModal').onclick=closeModal;
function licenseChip(spec){return `<span class="license-chip ${spec.license==='FOSS'?'':'restricted'}">${esc(spec.license)}${spec.spdx?' · '+esc(spec.spdx):''}</span>`;}
function glyph(spec){return `<span class="node-glyph" style="--node-color:${colors[spec.group]||'#99aabb'}">${glyphs[spec.group]||'◇'}</span>`;}
function defaults(spec){return Object.fromEntries(spec.parameters.map(p=>[p.key,p.default]));}
const canvas=new GraphCanvas($('#graphCanvas'),$('#minimap'),{onSelect:selectNode,beforeMove:()=>remember(),onMove:()=>changed(false),onDrop:(tool,p)=>addNode(tool,p),onEmptyDoubleClick:()=>$('#librarySearch').focus(),onZoom:k=>$('#zoomLabel').textContent=Math.round(k*100)+'%',onWireStart:hit=>{state.wire=hit;renderInspector();},onWireEnd:()=>{state.wire=null;renderInspector();},onConnect:guarded(connectNodes)});
const worker=new Worker('/static/graph-worker.js',{type:'module'});
worker.onmessage=({data})=>{const callback=state.workerReplies.get(data.id);if(callback){state.workerReplies.delete(data.id);callback(data);}if(data.version===state.version&&data.result?.issues){state.issues=data.result.issues;updateIssueCount();if(!state.selected)renderInspector();if(state.bottom==='copilot'&&!state.check)renderBottom();}};
function workerAnalyze(graph=state.graph){const id=++state.lastWorker;worker.postMessage({id,version:state.version,kind:'analyze',graph,definitions:state.nodes});}
async function validCandidate(graph){const id=++state.lastWorker;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{state.workerReplies.delete(id);reject(new Error('Graph validation worker timed out'));},5000);state.workerReplies.set(id,msg=>{clearTimeout(timer);msg.error?reject(new Error(msg.error)):resolve(msg.result);});worker.postMessage({id,version:-1,kind:'analyze',graph,definitions:state.nodes});});}
function remember(){state.history.push(clone(state.graph));if(state.history.length>60)state.history.shift();state.future=[];}
function changed(history=true){if(history)remember();state.version++;state.check=null;canvas.setGraph(state.graph,state.nodes);$('#projectLabel').textContent=state.graph.name;$('#graphStats').textContent=state.graph.nodes.length+' nodes · '+state.graph.edges.length+' connections';$('#emptyCanvas').hidden=!!state.graph.nodes.length;$('#saveStatus').textContent='Unsaved changes';workerAnalyze();renderInspector();if(state.library==='outline')renderLibrary();clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>saveGraph(),550);}
async function saveGraph(){const snapshot=clone(state.graph),id=state.graphId;state.savePromise=state.savePromise.catch(()=>{}).then(async()=>{try{const result=await api('/graphs/'+id,{method:'PUT',body:{graph:snapshot,revision:state.revision}});if(id===state.graphId){state.revision=result.revision;$('#saveStatus').textContent='All changes saved';}}catch(e){$('#saveStatus').textContent='Save failed';toast(e.message,true);}});return state.savePromise;}
function replaceGraph(g,id=null,revision=0){clearTimeout(state.saveTimer);state.graph=clone(g);state.graphId=id||uid('g_');state.revision=revision;state.selected=null;state.history=[];state.future=[];state.check=null;state.statuses.clear();canvas.status=state.statuses;changed(false);setTimeout(()=>canvas.fit(),30);}
function addNode(tool,p=null,params={}){document.body.classList.remove('library-open');const s=state.defs.get(tool);if(!s)return;remember();const center=canvas.world(canvas.width/2,canvas.height/2);const n={id:uid('n_'),tool,x:p?.x??center.x-103,y:p?.y??center.y-60,params:{...defaults(s),...params},resources:{threads:1,memory_mb:1024,timeout_seconds:s.builtin?30:120},advanced:''};state.graph.nodes.push(n);selectNode(n.id);changed(false);return n;}
function selectNode(id){if(id&&window.innerWidth<651)document.body.classList.add('inspector-open');state.selected=id;canvas.selected=id;canvas.invalidate();$('#selectionToolbar').hidden=!id;renderInspector();if(state.library==='outline')renderLibrary();}
async function connectNodes(edge){if(edge.source===edge.target)throw new Error('A node cannot connect to itself.');const candidate=clone(state.graph);const spec=state.defs.get(candidate.nodes.find(n=>n.id===edge.target).tool);const port=spec.inputs.find(p=>p.key===edge.targetPort);if(!port.many)candidate.edges=candidate.edges.filter(e=>!(e.target===edge.target&&e.targetPort===edge.targetPort));candidate.edges.push({...edge,id:uid('e_')});const result=await validCandidate(candidate);if(result.cycle)throw new Error('That connection creates a cycle.');remember();state.graph=candidate;changed(false);const mismatch=result.issues.find(i=>i.code==='FORMAT_MISMATCH'&&i.edge_id===candidate.edges.at(-1).id);if(mismatch){state.bottom='copilot';renderBottom();toast(mismatch.adapters?'Conversion available. Use Auto-Fix to insert explicit adapter nodes.':'These biological data types have no safe automatic conversion.',!mismatch.adapters);}else toast('Connection added');}
function deleteSelection(){if(!state.selected)return;remember();state.graph.nodes=state.graph.nodes.filter(n=>n.id!==state.selected);state.graph.edges=state.graph.edges.filter(e=>e.source!==state.selected&&e.target!==state.selected);selectNode(null);changed(false);}
function undo(){if(!state.history.length)return;state.future.push(clone(state.graph));state.graph=state.history.pop();changed(false);}
function redo(){if(!state.future.length)return;state.history.push(clone(state.graph));state.graph=state.future.pop();changed(false);}
$('#undoButton').onclick=undo;$('#redoButton').onclick=redo;$('#deleteNode').onclick=deleteSelection;
$('#duplicateNode').onclick=()=>{const n=state.graph.nodes.find(n=>n.id===state.selected);if(n){remember();const copy={...clone(n),id:uid('n_'),x:n.x+35,y:n.y+45};state.graph.nodes.push(copy);selectNode(copy.id);changed(false);}};
$('#fitButton').onclick=()=>canvas.fit();$('#zoomIn').onclick=()=>canvas.zoom(1.2);$('#zoomOut').onclick=()=>canvas.zoom(1/1.2);$('#tidyButton').onclick=()=>{remember();arrange(state.graph,state.nodes);changed(false);canvas.fit();};
function renderLibrary(){const content=$('#libraryContent'),term=$('#librarySearch').value.toLowerCase();$$('#libraryTabs button').forEach(b=>b.classList.toggle('active',b.dataset.library===state.library));$('#categoryBar').hidden=state.library!=='all';
 if(state.library==='outline'){content.innerHTML=state.graph.nodes.length?state.graph.nodes.map(n=>{const s=state.defs.get(n.tool);return `<button class="outline-row ${n.id===state.selected?'active':''}" data-select="${n.id}">${glyph(s)}<span>${esc(s.name)}<small style="display:block">${esc(n.id.slice(-7))}</small></span></button>`;}).join(''):'<div class="empty-state">The graph is empty.</div>';content.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>selectNode(b.dataset.select));return;}
 if(state.library==='assets'){const matches=state.assets.filter(a=>[a.name,a.family,a.format].join(' ').toLowerCase().includes(term));content.innerHTML=`<div class="action-row" style="padding:8px"><button class="button quiet" id="scanShortcut">Scan SSD</button><button class="button quiet" id="uploadShortcut">Upload file</button></div>`+(matches.length?matches.map(a=>`<div class="asset-card"><strong>${esc(a.name)}</strong><small>${esc(a.format)} · ${bytes(a.bytes)} · ${esc(a.assembly||a.family)}</small><div class="actions"><button data-add-asset="${a.id}">＋ Add to graph</button><button data-sync="${a.id}">Sync to AWS</button></div></div>`).join(''):'<div class="empty-state"><strong>Your data, close at hand.</strong>Scan a registered SSD directory or upload a small genomic file. Files stay in place until explicitly synced.</div>');$('#scanShortcut').onclick=()=>showSettings('data');$('#uploadShortcut').onclick=()=>$('#dataFile').click();content.querySelectorAll('[data-add-asset]').forEach(b=>b.onclick=()=>{const a=state.assets.find(x=>x.id===b.dataset.addAsset);addNode(a.format==='FASTA'?'reference.asset':'asset.file',null,{asset_id:a.id,...(a.assembly?{assembly:a.assembly}:{})});});content.querySelectorAll('[data-sync]').forEach(b=>b.onclick=guarded(async()=>{const result=await api('/assets/'+b.dataset.sync+'/sync',{method:'POST',body:{}});toast('Transfer admitted. Hashing and upload progress appear in Settings.');showSettings('data');}));return;}
 if(state.library==='public'){content.innerHTML=state.public.filter(p=>[p.name,p.family].join(' ').toLowerCase().includes(term)).map(p=>`<div class="asset-card"><strong>${esc(p.name)}</strong><small>${esc(p.region||'Provider-hosted')} · ${esc(p.format)}</small><small>${esc(p.license)}</small><div class="actions"><button data-probe="${p.id}">Check availability</button><button data-resolve="${esc(p.family)}">Find fastest source</button></div><small data-probe-result="${p.id}"></small></div>`).join('');content.querySelectorAll('[data-probe]').forEach(b=>b.onclick=guarded(async()=>{b.disabled=true;b.textContent='Checking…';try{const r=await api('/public/'+b.dataset.probe+'/probe',{method:'POST',body:{}});content.querySelector(`[data-probe-result="${b.dataset.probe}"]`).textContent=r.available?'Available'+(r.bytes?' · '+bytes(r.bytes):'')+' · '+(r.region||'provider'):(r.error||'Unavailable, HTTP '+r.status);}finally{b.disabled=false;b.textContent='Check availability';}}));content.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=guarded(async()=>{const r=await api('/data/resolve?family='+encodeURIComponent(b.dataset.resolve));openModal('Data resolution',r.candidates.length?r.candidates.map(c=>`<div class="asset-card"><strong>${esc(c.name)}</strong><small>${esc(c.kind.toUpperCase())} · ${esc(c.region||'Local SSD')}</small><p>${esc(c.reason)}</p>${c.uri?`<div class="mono">${esc(c.uri)}</div>`:''}</div>`).join(''):'<p>No indexed candidate exists yet. Scan your SSD reference directory.</p>','DATA ENGINE');}));return;}
 const filtered=state.nodes.filter(n=>(state.category==='All'||n.group===state.category)&&[n.name,n.group,n.description,n.id].join(' ').toLowerCase().includes(term));const groups=[...new Set(filtered.map(n=>n.group))];content.innerHTML=groups.map(group=>`<div class="library-heading">${esc(group)}<span>${filtered.filter(n=>n.group===group).length}</span></div>`+filtered.filter(n=>n.group===group).map(n=>`<div class="library-row" role="button" tabindex="0" draggable="true" data-tool="${n.id}" title="${esc(n.description)}">${glyph(n)}<div><div class="node-name">${esc(n.name)}</div><div class="node-desc">${n.builtin?'Portable operation':n.license==='FOSS'?(n.spdx||'Native container'):esc(n.license)}${n.quarantined?' · QUARANTINED':''}</div></div><span class="add-mark">＋</span></div>`).join('')).join('')||'<div class="empty-state">No matching nodes.</div>';
 content.querySelectorAll('[data-tool]').forEach(el=>{el.ondragstart=e=>e.dataTransfer.setData('application/ngs-tool',el.dataset.tool);el.ondblclick=()=>addNode(el.dataset.tool);el.onkeydown=e=>{if(e.key==='Enter')addNode(el.dataset.tool);};el.onclick=()=>{const spec=state.defs.get(el.dataset.tool);if(!state.selected)renderToolPreview(spec);};});}
function renderCategories(){const cats=['All','Samples','QC','Alignment','Variants','AI models','Adapters','Validation','Flow control','Cohorts'];$('#categoryBar').innerHTML=cats.map(c=>`<button data-category="${c}" class="${state.category===c?'active':''}">${esc(c)}</button>`).join('');$('#categoryBar').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;renderCategories();renderLibrary();});}
$('#librarySearch').oninput=()=>{renderLibrary();if(state.library==='assets'){clearTimeout(assetSearchTimer);assetSearchTimer=setTimeout(guarded(async()=>{await refreshAssets($('#librarySearch').value);renderLibrary();}),250);}};
$$('#libraryTabs button').forEach(b=>b.onclick=()=>{state.library=b.dataset.library;renderLibrary();});
function renderToolPreview(spec){$('#inspectorTag').textContent='LIBRARY';$('#inspectorContent').innerHTML=`<section class="inspector-section"><div class="inspector-identity">${glyph(spec)}<div><div class="eyebrow">${esc(spec.group)}</div><h2>${esc(spec.name)}</h2></div></div><p class="description">${esc(spec.description)}</p>${licenseChip(spec)}<button id="addPreviewNode" class="button quiet full" style="margin-top:18px">＋ Add to pipeline</button></section><section class="inspector-section"><div class="eyebrow">INTERFACE</div>${[...spec.inputs.map(p=>({...p,dir:'Input'})),...spec.outputs.map(p=>({...p,dir:'Output'}))].map(p=>`<div class="port-row"><span class="port-dot"></span>${esc(p.key)}<small>${p.dir} · ${esc(p.type)}</small></div>`).join('')}<p class="description">${spec.builtin?'Executes through the bounded portable worker.':'Native execution requires an approved runtime image and compatible backend.'}</p></section>`;$('#addPreviewNode').onclick=()=>addNode(spec.id);}
function renderInspector(){const n=state.graph.nodes.find(n=>n.id===state.selected);$('#inspectorTag').textContent=n?'NODE':'PIPELINE';if(!n){const lic=Object.entries(state.check?.licenses||state.graph.nodes.reduce((a,n)=>{const l=state.defs.get(n.tool)?.license||'Unknown';a[l]=(a[l]||0)+1;return a;},{}));$('#inspectorContent').innerHTML=`<section class="inspector-section"><div class="eyebrow">CURRENT ANALYSIS</div><h2 style="font-size:18px;font-weight:450;margin-top:7px">A connected workflow.<br>A reproducible result.</h2><p class="description">Select a node to tune its scientific parameters, inspect its data contract and discover compatible next steps.</p><div class="metric-grid"><div class="metric"><strong>${state.graph.nodes.length}</strong><span>Analysis nodes</span></div><div class="metric"><strong>${state.graph.edges.length}</strong><span>Connections</span></div></div></section><section class="inspector-section"><div class="section-label">WORKSPACE COMPUTE <span class="badge">${esc(state.user?.tier||'trial')}</span></div>${quotaMarkup()}<p class="description">Compute is reserved before launch. Stop requests cancel work; released capacity appears after termination is confirmed.</p></section><section class="inspector-section"><div class="section-label">PIPELINE RIGHTS</div>${lic.map(([l,c])=>`<div class="port-row"><span class="port-dot"></span>${esc(l)}<small>${c} nodes</small></div>`).join('')}<p class="description">Tool code, models and databases can have different terms. Platform access does not grant third-party rights.</p></section><section class="inspector-section"><div class="eyebrow">RESEARCH WORKSPACE</div><p class="description">NGS is an independent module. Shared artifact and assay contracts prepare it for future spatial and multiomics integration.</p></section>`;return;}
 const s=state.defs.get(n.tool);const params={...defaults(s),...n.params};let fields=s.parameters.map(p=>{let control;if(p.kind==='boolean')return `<div class="field"><label class="toggle-label">${esc(p.label)}<input type="checkbox" data-param="${p.key}" ${params[p.key]?'checked':''}></label>${p.tip?`<small>${esc(p.tip)}</small>`:''}</div>`;if(p.kind==='select')control=`<select data-param="${p.key}">${p.options.map(v=>`<option ${v===params[p.key]?'selected':''}>${esc(v)}</option>`).join('')}</select>`;else if(p.kind==='asset'){const filter=n.tool==='reference.asset'||s.asset_family==='reference'?'FASTA':n.tool==='database.asset'||s.asset_family?'DATABASE':null;let assets=[...new Map([...state.assets,...(s.asset_candidates||[])].map(a=>[a.id,a])).values()].filter(a=>!filter||a.format===filter||filter==='DATABASE'&&['INDEX','INDEXED_VCF','VCF','DATABASE'].includes(a.format));control=`<select data-param="${p.key}"><option value="">Select an indexed asset…</option>${assets.map(a=>`<option value="${a.id}" ${a.id===params[p.key]?'selected':''}>${esc(a.name)} · ${bytes(a.bytes)}</option>`).join('')}</select><small><button class="quiet" data-asset-picker="${p.key}">Search all indexed assets ↗</button><button class="quiet" id="inspectScan">Manage SSD ↗</button></small>`;}else control=`<input data-param="${p.key}" type="${p.kind==='number'?'number':'text'}" value="${esc(params[p.key])}" ${p.min!==undefined?'min="'+p.min+'"':''} ${p.max!==undefined?'max="'+p.max+'"':''} ${p.step!==undefined?'step="'+p.step+'"':''}>`;return `<div class="field"><label>${esc(p.label)}</label>${control}${p.tip?`<small>${esc(p.tip)}</small>`:''}</div>`;}).join('');
 const suggestions=compatibleSuggestions(n,s);const issues=(state.check?.issues||state.issues).filter(x=>x.node_id===n.id);$('#inspectorContent').innerHTML=`<section class="inspector-section"><div class="inspector-identity">${glyph(s)}<div><div class="eyebrow">${esc(s.group)} · V${esc(s.version)}</div><h2>${esc(s.name)}</h2></div></div><p class="description">${esc(s.description)}</p>${licenseChip(s)}${s.credential?'<button id="unlockCredential" class="button quiet full" style="margin-top:12px">Bind / review key or license ↗</button><p class="tiny muted">A saved key is not proof of vendor entitlement. Provider validation and runtime checks apply before execution.</p>':''}${s.quarantined?`<div class="inline-error">Quarantined: ${esc(s.quarantined)}</div>`:''}${issues.map(i=>`<div class="inline-error">${esc(i.message)}</div>`).join('')}</section><section class="inspector-section"><div class="section-label">SCIENTIFIC PARAMETERS <span class="muted">${s.parameters.length}</span></div>${fields||'<p class="description">This operation has no scientific tuning parameters. Its input and runtime limits remain explicit.</p>'}${s.id==='custom'||s.id.startsWith('custom_')?'<p class="description">Named inputs and output files are fixed by the published container contract.</p>':''}</section><section class="inspector-section"><div class="section-label">RESOURCES</div><div class="field-grid">${[['threads','vCPU'],['memory_mb','Memory · MiB'],['scratch_mb','Scratch · MiB']].map(([k,l])=>`<div class="field"><label>${l}</label><input type="number" min="1" data-resource="${k}" value="${n.resources[k]??2048}"></div>`).join('')}</div><div class="field"><label>Wall-time ceiling <span class="muted">seconds</span></label><input type="number" min="1" data-resource="timeout_seconds" value="${n.resources.timeout_seconds}"></div>${!s.builtin?`<details><summary class="tiny">Advanced CLI arguments</summary><div class="field"><textarea data-advanced rows="3" spellcheck="false" placeholder="Additional tool flags">${esc(n.advanced||'')}</textarea><small>Parsed as argv. Commands never execute in a host shell. Resource and licence gates still apply.</small></div></details>`:''}${!s.builtin&&s.license==='FOSS'?'<button id="resolveNodeImage" class="button quiet full" style="margin-top:10px">Resolve execution image</button>':''}</section><section class="inspector-section"><div class="section-label">DATA CONNECTIONS</div>${s.inputs.map(p=>{const edge=state.graph.edges.find(e=>e.target===n.id&&e.targetPort===p.key);return `<div class="port-row"><span class="port-dot"></span>${esc(p.key)}<small>${edge?'Connected':p.required?'Required':'Optional'}</small>${edge?`<button data-disconnect="${edge.id}" title="Disconnect input">×</button>`:''}</div>`;}).join('')}${s.outputs.map(p=>`<div class="port-row"><span class="port-dot"></span>${esc(p.key)}<small>${esc(p.type)} ↗</small></div>`).join('')}</section><section class="inspector-section"><div class="section-label">${state.wire?.direction==='input'?'COMPATIBLE UPSTREAM':'COMPATIBLE NEXT STEPS'}<span class="tiny">${suggestions.length}</span></div>${suggestions.slice(0,8).map(item=>`<button class="suggestion" data-suggest="${item.spec.id}" data-port="${esc(item.port)}" data-from-port="${esc(item.sourcePort)}" data-upstream="${item.upstream?'1':'0'}">${glyph(item.spec)}<span><span class="name">${esc(item.spec.name)}</span><small>${item.adapters?.length?'Via '+item.adapters.map(x=>state.defs.get(x).name).join(' → '):'Direct '+esc(item.port)+' connection'}</small></span><span class="add-mark">＋</span></button>`).join('')||'<p class="description">No compatible published nodes for this port.</p>'}<p class="description">Adapters change representations only. Reference build, sample roles and model context are checked separately.</p></section>${s.docs&&s.docs.startsWith('https://')?`<section class="inspector-section"><a target="_blank" rel="noopener noreferrer" href="${esc(s.docs)}" class="tiny">Upstream documentation ↗</a>${s.rights_note?`<p class="description">${esc(s.rights_note)}</p>`:''}</section>`:''}`;
 $('#inspectorContent').querySelectorAll('[data-param]').forEach(el=>el.onchange=()=>{remember();const def=s.parameters.find(p=>p.key===el.dataset.param);n.params[el.dataset.param]=def.kind==='boolean'?el.checked:def.kind==='number'||def.kind==='select'&&typeof def.default==='number'?Number(el.value):el.value;changed(false);if(def.kind==='asset'&&el.value)api('/assets/'+el.value+'/inspect',{method:'POST',body:{}}).then(r=>{const asset=state.assets.find(a=>a.id===r.id);if(asset)Object.assign(asset,r);toast('Header and index contract inspected');}).catch(e=>toast('Header review: '+e.message,true));});$('#inspectorContent').querySelectorAll('[data-resource]').forEach(el=>el.onchange=()=>{remember();n.resources[el.dataset.resource]=Number(el.value);changed(false);});$('#unlockCredential')?.addEventListener('click',guarded(async()=>{await showSettings('vault');$('#vaultProvider').value=s.credential;$('#vaultBindings').value=s.id;}));const advanced=$('[data-advanced]');if(advanced)advanced.onchange=()=>{remember();n.advanced=advanced.value;changed(false);};$('#inspectorContent').querySelectorAll('[data-asset-picker]').forEach(b=>b.onclick=guarded(()=>pickAsset(n,b.dataset.assetPicker)));$('#inspectScan')?.addEventListener('click',()=>showSettings('data'));$('#resolveNodeImage')?.addEventListener('click',guarded(()=>resolveNodeImage(s)));$('#inspectorContent').querySelectorAll('[data-disconnect]').forEach(b=>b.onclick=()=>{remember();state.graph.edges=state.graph.edges.filter(e=>e.id!==b.dataset.disconnect);changed(false);});$('#inspectorContent').querySelectorAll('[data-suggest]').forEach(b=>b.onclick=guarded(async()=>{const original=n;const next=addNode(b.dataset.suggest,{x:n.x+(b.dataset.upstream==='1'?-280:280),y:n.y});await connectNodes(b.dataset.upstream==='1'?{source:next.id,sourcePort:b.dataset.port,target:original.id,targetPort:b.dataset.fromPort}:{source:original.id,sourcePort:b.dataset.fromPort,target:next.id,targetPort:b.dataset.port});}));}
function compatibleSuggestions(n,s){const result=[];const upstream=state.wire?.direction==='input';const ports=state.wire?[state.wire.port]:s.outputs;for(const other of state.nodes){if(other.id===s.id||other.group==='Assets'||other.group==='Commercial')continue;for(const source of ports){for(const target of (upstream?other.outputs:other.inputs)){const route=adapterPath(upstream?target.type:source.type,upstream?source.type:target.type,state.nodes);if(route!==null){result.push({spec:other,port:target.key,sourcePort:source.key,adapters:route,upstream});break;}}if(result.at(-1)?.spec===other)break;}}return result.sort((a,b)=>a.adapters.length-b.adapters.length||Number(!a.spec.builtin)-Number(!b.spec.builtin));}
function quotaMarkup(){const u=state.user||{quota_seconds:1,used_seconds:0,reserved_seconds:0};const exposure=u.used_seconds+u.reserved_seconds;return `<div class="progress-track"><span style="width:${Math.min(100,100*exposure/Math.max(1,u.quota_seconds))}%"></span></div><div class="quota-caption"><span>${duration(u.used_seconds)} used · ${duration(u.reserved_seconds)} reserved</span><span>${duration(u.quota_seconds)}</span></div>`;}
function updateIssueCount(){const n=(state.check?.issues||state.issues).length;$('#issueCount').textContent=n?'· '+n:'';}
function setBottom(name){state.bottom=name;renderBottom();}
$$('#bottomTabs button').forEach(b=>b.onclick=()=>setBottom(b.dataset.bottom));
function renderBottom(){const el=$('#bottomContent');$$('#bottomTabs button').forEach(b=>b.classList.toggle('active',b.dataset.bottom===state.bottom));el.classList.toggle('terminal',state.bottom==='logs');$('#logCount').textContent=state.logs.length;$('#outputCount').textContent=state.outputs.length;updateIssueCount();
 if(state.bottom==='logs'){const atEnd=el.scrollHeight-el.scrollTop-el.clientHeight<60;el.innerHTML=state.logs.length?state.logs.slice(-400).map(l=>`<div class="log-line"><span class="log-time">${new Date(l.at*1000).toLocaleTimeString()}</span><span class="log-node">${esc(state.defs.get(state.graph.nodes.find(n=>n.id===l.node_id)?.tool)?.name||'Pipeline')}</span><span class="log-text">${esc(l.payload.text||l.payload.error||l.kind)}</span></div>`).join(''):'<span class="muted">Diagnostics stream here during execution. No simulated log lines.</span>';if(atEnd)el.scrollTop=el.scrollHeight;return;}
 if(state.bottom==='outputs'){el.innerHTML=state.outputs.length?state.outputs.map(a=>`<div class="output-row"><span class="node-glyph">↧</span><div><strong>${esc(a.name)}</strong><small>${esc(a.format)} · ${bytes(a.bytes)} · ${esc(a.digest?.slice(0,22)||'source asset')}</small></div><button data-inspect-output="${a.id}" class="button quiet">Inspect</button><a class="button quiet" href="/api/artifacts/${a.id}" download>Download</a></div>`).join(''):'<div class="empty-state"><strong>Results stay connected to their source.</strong>Run a pipeline to publish files, report metrics and content hashes here.</div>';el.querySelectorAll('[data-inspect-output]').forEach(b=>b.onclick=guarded(()=>showArtifact(b.dataset.inspectOutput)));return;}
 if(state.bottom==='copilot'){const issues=state.check?.issues||state.issues;const fixable=issues.some(i=>i.fix||i.adapters?.length);el.innerHTML=`<div class="copilot-layout"><span class="copilot-icon">✧</span><div class="copilot-body"><h3>${issues.length?issues.length+' checks need attention':state.run?.state==='failed'?'The run stopped safely.':'Your graph is connected.'}</h3><p>${state.run?.state==='failed'?esc(state.run.error||'Select the failed node and inspect its diagnostic log.'):issues.length?'The helper explains actual graph and execution checks. Auto-Fix inserts explicit representation adapters or removes dangling connections.':'Server preflight will verify runtime availability, data ownership, reference context, rights and quota before execution.'}</p>${issues.slice(0,30).map(i=>`<div class="issue-row"><span class="code">${esc(i.code)}</span><span>${esc(i.message)}</span>${i.node_id?`<button data-jump="${i.node_id}">Inspect node ↗</button>`:''}</div>`).join('')}</div>${fixable?'<button id="autoFixButton" class="button primary">✧ Auto-Fix graph</button>':'<button id="copilotValidate" class="button quiet">Run full preflight</button>'}</div>`;el.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>selectNode(b.dataset.jump));$('#autoFixButton')?.addEventListener('click',guarded(async()=>{const r=await api('/graph/fix',{method:'POST',body:{graph:state.graph}});remember();state.graph=r.graph;changed(false);state.check=r.preflight;renderBottom();toast(r.applied+' explicit fixes applied');}));$('#copilotValidate')?.addEventListener('click',guarded(()=>validateGraph()));return;}
 if(!state.run){el.innerHTML=`<div class="ready-layout"><div class="ready-icon">⌘</div><div><h3>Your pipeline is ready to explore.</h3><p>The starter uses 1,000 synthetic read pairs and produces a real quality report. Choose GIAB or RNA-seq from Templates to work with public scientific data.</p><div class="action-row" style="margin-top:13px"><button id="readyRun" class="button primary">▶ Run this pipeline</button><button id="readyTemplates" class="quiet">Browse sample workflows ↗</button></div></div><div class="spacer"></div><div class="ready-stats"><span>AVAILABLE COMPUTE</span><strong>${duration((state.user?.quota_seconds||0)-(state.user?.used_seconds||0)-(state.user?.reserved_seconds||0))}</strong><span>Allocated vCPU time · ${esc(state.user?.tier||'trial')}</span></div></div>`;$('#readyRun').onclick=guarded(runPipeline);$('#readyTemplates').onclick=showTemplates;return;}
 const tasks=state.graph.nodes.slice(0,12).map(n=>{const s=state.defs.get(n.tool),t=state.statuses.get(n.id)||{},m=t.metrics||{};return `<div class="task-card"><div class="task-name"><span>${esc(s?.name||n.tool)}</span><span class="state-${esc(t.state||'queued')}">${t.state==='succeeded'?'✓':t.state==='running'?'◉':t.state==='failed'?'×':'·'}</span></div><small class="state-${esc(t.state||'queued')}">${esc(t.state||'queued')}</small><small>${m.elapsed_seconds!==undefined?duration(m.elapsed_seconds)+' · '+bytes(m.rss_bytes||0)+' RSS':'Awaiting worker'}</small></div>`;}).join('');el.innerHTML=`<div class="task-strip">${tasks}</div><div class="task-run-summary"><span class="state-${esc(state.run.state)}">● ${esc(state.run.state.toUpperCase())}</span><span>${esc(state.run.id.slice(-12))}</span><span>${duration(state.run.used||0)} allocated CPU time</span>${state.run.error?`<span class="danger">${esc(state.run.error)}</span>`:''}<span class="spacer"></span><button id="viewResults" class="quiet">View ${state.outputs.length} outputs ↗</button></div>`;$('#viewResults').onclick=()=>setBottom('outputs');}
async function validateGraph(){const r=await api('/graph/preflight',{method:'POST',body:{graph:state.graph}});state.check=r;state.bottom='copilot';renderInspector();renderBottom();toast(r.ok?'Preflight passed · '+duration(r.reservation_cpu_seconds)+' worst-case CPU reservation':r.issues.length+' checks need attention',!r.ok);return r;}
async function runPipeline(){const checked=await validateGraph();if(!checked.ok)return;await saveGraph();$('#runButton').disabled=true;try{const r=await api('/runs',{method:'POST',headers:{'Idempotency-Key':uid('op_')},body:{graph:state.graph}});state.run=r.run;state.logs=[];state.statuses.clear();canvas.status=state.statuses;state.outputs=[];setBottom('execution');watchRun(r.run.id);await refreshSession();}finally{$('#runButton').disabled=false;}}
function watchRun(rid){state.source?.close();const source=new EventSource('/api/runs/'+rid+'/events');state.source=source;$('#stopButton').disabled=false;$('#connectionStatus').textContent='Execution stream connected';source.onmessage=e=>{const event=JSON.parse(e.data),p=event.payload;if(event.kind==='run.state'){state.run={...state.run,...p};if(p.state==='running')$('#runButton').disabled=true;}if(event.kind==='task.state'){const old=state.statuses.get(event.node_id)||{};state.statuses.set(event.node_id,{...old,...p});canvas.invalidate();}if(event.kind==='task.metrics'){const old=state.statuses.get(event.node_id)||{};state.statuses.set(event.node_id,{...old,metrics:p});}if(event.kind==='log'||p.error){state.logs.push(event);if(state.logs.length>2000)state.logs.splice(0,state.logs.length-2000);}clearTimeout(logRenderTimer);logRenderTimer=setTimeout(()=>{if(['logs','execution'].includes(state.bottom))renderBottom();},90);};source.addEventListener('complete',guarded(async()=>{source.close();$('#stopButton').disabled=true;$('#runButton').disabled=false;$('#connectionStatus').textContent='Workspace connected';await loadRun(rid,false);await refreshSession();toast(state.run.state==='succeeded'?'Pipeline completed · '+state.outputs.length+' artifacts published':state.run.error||state.run.state,state.run.state!=='succeeded');}));source.onerror=()=>{$('#connectionStatus').textContent='Reconnecting execution stream…';};}
async function loadRun(rid,replay=true){const r=await api('/runs/'+rid);state.run=r.run;state.outputs=r.artifacts;state.attempts=r.attempts;state.statuses.clear();for(const a of r.attempts)state.statuses.set(a.node_id,{state:a.state,metrics:a.metrics,error:a.error});canvas.status=state.statuses;canvas.invalidate();if(replay&&!['succeeded','failed','cancelled','interrupted'].includes(r.run.state))watchRun(rid);renderBottom();}
$('#runButton').onclick=guarded(runPipeline);$('#validateButton').onclick=guarded(validateGraph);$('#stopButton').onclick=guarded(async()=>{if(state.run){await api('/runs/'+state.run.id+'/cancel',{method:'POST',body:{}});toast('Cancellation requested. Waiting for worker termination.');}});$('#designMode').onclick=()=>{$('#designMode').classList.add('active');$('#executionMode').classList.remove('active');};$('#executionMode').onclick=()=>{$('#executionMode').classList.add('active');$('#designMode').classList.remove('active');setBottom('execution');};
async function showArtifact(id){const a=await api('/artifacts/'+id+'?metadata=1');if(extensions.variants.has(a.format))return extensions.open(id);if(['H5AD','TSV','CSV','QUANT'].includes(a.format))return extensions.openOmics(id);const r=a.metadata?.report;openModal(a.name,`<div class="action-row"><span class="badge">${esc(a.format)}</span><span class="badge">${bytes(a.bytes)}</span><a class="button quiet" href="/api/artifacts/${id}" download>Download source</a></div>${r?.mates?`<div class="metric-grid"><div class="metric"><strong>${r.total_reads.toLocaleString()}</strong><span>Reads measured</span></div><div class="metric"><strong>${r.mates[0].q30_percent.toFixed(1)}%</strong><span>Mate 1 · Q30 bases</span></div></div>`:r?.records!==undefined?`<div class="metric-grid"><div class="metric"><strong>${r.records.toLocaleString()}</strong><span>VCF records</span></div><div class="metric"><strong>${Object.keys(r.chromosomes).length}</strong><span>Contigs observed</span></div></div>`:''}<div class="note mono">${esc(a.digest||'Original source asset')}</div><pre class="mono" style="white-space:pre-wrap;max-height:450px;overflow:auto">${esc(JSON.stringify(r||a.metadata,null,2))}</pre>`,'RUN ARTIFACT');}
function showTemplates(){openModal('Start from a proven shape.',`<p>Templates provide explicit wiring and parameters. Native and vendor workflows still pass the same runtime, rights and data checks.</p><div class="template-grid">${state.templates.map(t=>`<button class="template-card" data-template="${t.id}"><span class="eyebrow">${t.id==='quickstart'?'ENGINEERING FIXTURE':t.id==='giab'||t.id==='rna-qc'?'PUBLIC SCIENTIFIC DATA':'NATIVE WORKFLOW'}</span><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><div class="mini-pipeline">${t.graph.nodes.slice(0,6).map(()=>'<span></span>').join(' → ')}</div><small>${t.graph.nodes.length} nodes · ${t.graph.edges.length} connections</small></button>`).join('')}</div>`,'PIPELINE TEMPLATES');modalClick('[data-template]',async(e,b)=>{await saveGraph();const t=state.templates.find(t=>t.id===b.dataset.template);replaceGraph(t.graph);state.run=null;state.outputs=[];state.logs=[];closeModal();renderBottom();});}
$('#templatesButton').onclick=showTemplates;$('#emptyTemplateButton').onclick=showTemplates;$('#newButton').onclick=guarded(async()=>{await saveGraph();replaceGraph({name:'Untitled pipeline',nodes:[],edges:[]});state.run=null;state.outputs=[];renderBottom();});
$('#exportButton').onclick=()=>{const blob=new Blob([JSON.stringify({schema_version:'1.0.0',...state.graph},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=state.graph.name.replace(/[^a-zA-Z0-9_-]/g,'_')+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);};$('#importButton').onclick=()=>$('#graphFile').click();$('#graphFile').onchange=guarded(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1800000)throw new Error('Graph file exceeds the 1.8 MB limit');const g=JSON.parse(await file.text());if(!Array.isArray(g.nodes)||!Array.isArray(g.edges))throw new Error('This file is not a Studio graph');await api('/graph/preflight',{method:'POST',body:{graph:g}});replaceGraph(g);e.target.value='';});
$('#pipelineMenu').onclick=guarded(async()=>{const graphs=await api('/graphs');openModal('Your pipelines',`<div class="field"><label>Current pipeline name</label><input id="renameGraph" value="${esc(state.graph.name)}"></div><button id="renameSave" class="button quiet">Save name</button><h3 style="margin-top:24px">Saved analyses</h3>${graphs.map(g=>`<button class="outline-row" data-load-graph="${g.id}"><span>◇</span><span>${esc(g.name)}<small style="display:block">Revision ${g.revision} · ${new Date(g.updated*1000).toLocaleString()}</small></span><span class="spacer"></span>↗</button>`).join('')}`,'WORKSPACE');modalClick('#renameSave',()=>{remember();state.graph.name=$('#renameGraph').value.trim()||'Untitled pipeline';changed(false);closeModal();});modalClick('[data-load-graph]',async(e,b)=>{await saveGraph();const g=await api('/graphs/'+b.dataset.loadGraph);replaceGraph(g.body,g.id,g.revision);closeModal();});});
$('#runHistoryButton').onclick=guarded(async()=>{const runs=await api('/runs');openModal('Execution history',runs.length?`<table class="table"><thead><tr><th>Pipeline</th><th>State</th><th>Allocated CPU</th><th>Created</th><th></th></tr></thead><tbody>${runs.map(r=>`<tr><td>${esc(r.graph.name)}</td><td class="state-${esc(r.state)}">${esc(r.state)}</td><td>${duration(r.used)}</td><td>${new Date(r.created*1000).toLocaleString()}</td><td><button class="quiet" data-load-run="${r.id}">Open ↗</button></td></tr>`).join('')}</tbody></table>`:'<p>No executions yet. Run a sample template to create actual results.</p>','EXECUTIONS');modalClick('[data-load-run]',async(e,b)=>{const r=runs.find(r=>r.id===b.dataset.loadRun);replaceGraph(r.graph);state.bottom='execution';await loadRun(r.id);closeModal();});});
async function refreshSession(){const r=await api('/session');state.user=r.user;state.csrf=r.csrf;$('#tierLabel').textContent=r.user.tier[0].toUpperCase()+r.user.tier.slice(1);$('#adminButton').hidden=r.user.role!=='admin';$('#profileButton').textContent=r.user.email[0].toUpperCase();$('#quotaStatus').textContent=duration(Math.max(0,r.user.quota_seconds-r.user.used_seconds-r.user.reserved_seconds))+' CPU remaining';if(!state.selected)renderInspector();}
async function refreshAssets(q=''){const r=await api('/assets?q='+encodeURIComponent(q));state.assets=r.assets;state.public=r.public_sources;state.scans=r.scans;state.transfers=r.transfers;return r;}
function settingsTabs(tab){return `<nav class="tabs">${[['general','General'],['data','Data & runtime'],['trust','Trust & entitlements'],['vault','Credential vault']].map(([id,label])=>`<button data-settings-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</nav>`;}
async function showSettings(tab='general'){state.settings=await api('/settings');await refreshAssets();const s=state.settings;let html=settingsTabs(tab);
 if(tab==='general')html+=`<div class="settings-grid"><section class="settings-section"><div class="eyebrow">IDENTITY</div><h3>${esc(state.user.email)}</h3><p>${esc(state.user.role)} · authenticated desktop workspace</p><button id="logoutButton" class="button quiet">Sign out</button></section><section class="settings-section"><div class="eyebrow">APPEARANCE</div><div class="field"><label>Colour theme</label><select id="themeChoice"><option value="dark" ${s.theme==='dark'?'selected':''}>Spatial dark · navy</option><option value="light" ${s.theme==='light'?'selected':''}>Spatial light</option></select></div><p>Uses the recovered Spatial application’s exact colour tokens and system typography.</p></section></div><section class="settings-section"><div class="eyebrow">CANVAS PERFORMANCE</div><h3>Measure this device.</h3><p>Stress-test 500 nodes and 2,000 edges for 90 frames. Your pipeline is restored afterward. Reported numbers are measurements from this browser, not certification of a performance target.</p><button id="benchmarkButton" class="button quiet">Run renderer benchmark</button><pre id="benchmarkResult" class="mono"></pre></section><div class="note">This is a working desktop research deployment. Institutional SSO, immutable external audit checkpoints and hostile multi-tenant cloud isolation belong to the separate production deployment profile.</div>`;
 if(tab==='data')html+=`<div class="settings-grid"><section class="settings-section"><div class="eyebrow">EXTERNAL SSD</div><h3>Discover without copying.</h3><div class="field"><label>Registered data directories · one per line</label><textarea id="ssdRoots" rows="4">${esc(s.ssd_roots.join('\n'))}</textarea><small>Scanner reads file metadata and detects formats/indices. It does not hash or upload your collection.</small></div><div class="action-row"><button id="saveDataSettings" class="button quiet">Save paths & runtime</button><button id="scanNow" class="button primary">Scan registered paths</button><button id="browseSsd" class="quiet">Browse SSD</button></div><div id="scanProgress" class="note">${state.scans.length?state.scans.slice(0,3).map(x=>esc(x.state)+' · '+x.files+' files · '+bytes(x.bytes)).join('<br>'):'No scan has run yet.'}</div></section><section class="settings-section"><div class="eyebrow">EXECUTION</div><div class="field"><label>Backend</label><select id="runtimeBackend">${[['portable','Portable · built-in operations'],['docker','Docker · approved native containers'],['aws-batch','AWS Batch · published worker profiles']].map(([v,l])=>`<option value="${v}" ${s.backend===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field-grid"><div class="field"><label>Node wall-time limit · s</label><input id="maxNodeSeconds" type="number" value="${s.max_node_seconds}"></div><div class="field"><label>Upload ceiling · GiB</label><input id="maxUploadGib" type="number" value="${s.max_upload_gib}"></div></div><p>Docker available: <strong>${state.capabilities.docker?'yes':'no'}</strong>. Native images are resolved, pinned and approved before execution.</p></section></div><section class="settings-section"><div class="eyebrow">AWS · US-EAST-1</div><div class="settings-grid"><div class="field"><label>Private S3 cache bucket</label><input id="s3Bucket" value="${esc(s.s3_bucket)}"></div><div class="field"><label>KMS key ARN</label><input id="kmsKey" value="${esc(s.kms_key_arn)}"></div><div class="field"><label>AWS Batch queue ARN / name</label><input id="batchQueue" value="${esc(s.batch_queue)}"></div><div class="field"><label>Published worker job definition</label><input id="batchDefinition" value="${esc(s.batch_job_definition)}"></div></div><div class="action-row"><button id="saveCloudSettings" class="button primary">Save cloud settings</button><button id="cloudCheck" class="button quiet">Verify AWS connection</button></div><pre id="cloudCheckResult" class="mono"></pre></section><section class="settings-section"><div class="eyebrow">TRANSFERS</div>${state.transfers.length?state.transfers.map(t=>`<div class="vault-card"><div><strong>${esc(t.state)}</strong><small>${bytes(t.bytes)} / ${bytes(t.total)} ${t.error?'· '+esc(t.error):''}</small><div class="progress-track"><span style="width:${100*t.bytes/Math.max(1,t.total)}%"></span></div></div>${['hashing','uploading'].includes(t.state)?`<button class="quiet danger" data-cancel-transfer="${t.id}">Cancel</button>`:''}</div>`).join(''):'<p>Choose “Sync to AWS” on an SSD asset to start a content-addressed, parallel multipart transfer.</p>'}</section>`;
 if(tab==='trust')html+=`<section class="settings-section"><div class="eyebrow">PLATFORM ENTITLEMENT</div><h3>${esc(state.user.tier.toUpperCase())} · ${state.user.frozen?'Frozen':'Active'}</h3>${quotaMarkup()}<div class="metric-grid"><div class="metric"><strong>${duration(state.user.used_seconds)}</strong><span>Allocated CPU time used</span></div><div class="metric"><strong>${duration(state.user.reserved_seconds)}</strong><span>Outstanding reservation</span></div></div><p>The trial includes eight vCPU-hours, bounded execution and public/engineering samples. These are application CPU-time units, not a live exact AWS dollar bill.</p><button id="openTierAdmin" class="button quiet">${state.user.role==='admin'?'Manage tiers & quota':'Request tier review'}</button></section><section class="settings-section"><div class="eyebrow">THIRD-PARTY RIGHTS</div><p>Academic software, weights and databases are approved independently. A platform trial grants none of their rights.</p>${state.user.role==='admin'?state.nodes.filter(n=>['Academic','Commercial BYOL','Review required'].includes(n.license)).map(n=>`<label class="port-row"><input type="checkbox" data-rights="${n.id}" ${s.rights_approved.includes(n.id)?'checked':''}>${esc(n.name)}<small>${esc(n.license)}</small></label>`).join('')+'<button id="saveRights" class="button quiet">Record reviewed rights approvals</button>':'<p>Ask your workspace administrator to record verified agreements and usage scope.</p>'}</section>`;
 if(tab==='vault'){const entries=await api('/vault');html+=`<div class="note">Credentials are encrypted at rest and never returned by these APIs. With a configured KMS key, each secret uses a KMS-wrapped data key. Desktop mode uses a separate owner-readable local master file.</div><section class="settings-section"><div class="eyebrow">ADD OR ROTATE A CREDENTIAL</div><div class="settings-grid"><div class="field"><label>Provider / licence</label><select id="vaultProvider">${['franklin','oncokb','customapi','cosmic','openai','sentieon','dragen','hgmd','annovar'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Label</label><input id="vaultLabel" placeholder="Lab research account" autocomplete="off"></div></div><div class="field"><label>API key or licence token</label><input id="vaultValue" type="password" autocomplete="new-password" placeholder="Encrypted on save; never displayed again"></div><div class="field"><label>Allowed node IDs · comma separated</label><input id="vaultBindings" value="franklin"><small>Bindings use published registry IDs, for example oncokb, franklin or a custom tool ID.</small></div><button id="saveVault" class="button primary">Encrypt & save credential</button></section><h3>Stored credentials</h3>${entries.length?entries.map(v=>`<div class="vault-card"><span class="node-glyph">♧</span><div><strong>${esc(v.label)}</strong><small>${esc(v.provider)} · ${esc(v.mode)} · v${v.version} · ${v.revoked?'REVOKED':'active'}</small><small>Bound to ${esc(v.bindings.join(', ')||'no nodes')}</small></div><button data-check-secret="${v.id}" class="quiet" ${v.revoked?'disabled':''}>Check</button><button data-rotate-secret="${v.id}" class="quiet">Rotate</button><button data-revoke-secret="${v.id}" class="quiet danger" ${v.revoked?'disabled':''}>Revoke</button></div>`).join(''):'<p>No credentials stored. Public sample workflows do not need any.</p>'}`;state.vault=entries;}
 openModal('Workspace settings',html,'NGS STUDIO');modalClick('[data-settings-tab]',(e,b)=>showSettings(b.dataset.settingsTab));modalClick('#logoutButton',async()=>{await api('/logout',{method:'POST',body:{}});closeModal();location.reload();});$('#themeChoice')?.addEventListener('change',guarded(async e=>{await api('/settings',{method:'PATCH',body:{theme:e.target.value}});document.body.classList.toggle('light',e.target.value==='light');canvas.invalidate();}));modalClick('#benchmarkButton',async(e,b)=>{b.disabled=true;b.textContent='Measuring 500 nodes…';closeModal();const original=state.graph,view={...canvas.view},temporary={name:'Performance probe',nodes:[],edges:[]};for(let i=0;i<500;i++)temporary.nodes.push({id:'bench'+i,tool:'utility.gather',x:(i%25)*225,y:Math.floor(i/25)*135,params:{},resources:{}});for(let i=1;i<500;i++)for(let j=1;j<=4;j++)if(i>=j)temporary.edges.push({id:'be'+i+'_'+j,source:'bench'+(i-j),sourcePort:'collection',target:'bench'+i,targetPort:'items'});for(let j=10;j<20;j++)temporary.edges.push({id:'extra'+j,source:'bench0',sourcePort:'collection',target:'bench'+j,targetPort:'items'});canvas.setGraph(temporary,state.nodes);canvas.fit();await new Promise(r=>setTimeout(r,50));const result=await canvas.benchmark();canvas.setGraph(original,state.nodes);canvas.view=view;canvas.invalidate();$('#zoomLabel').textContent=Math.round(view.k*100)+'%';openModal('Canvas benchmark',`<p>Actual measurements from this browser. Edges with no matching port are omitted by the renderer, so this probe reports both submitted and drawable edges.</p><pre class="mono">${esc(JSON.stringify({...result,drawn_edges:temporary.edges.filter(e=>state.defs.get(temporary.nodes.find(n=>n.id===e.source).tool).outputs.some(p=>p.key===e.sourcePort)&&state.defs.get(temporary.nodes.find(n=>n.id===e.target).tool).inputs.some(p=>p.key===e.targetPort)).length},null,2))}</pre>`,'PERFORMANCE');});
 const saveData=async()=>{const roots=$('#ssdRoots').value.split('\n').map(x=>x.trim()).filter(Boolean);state.settings=await api('/settings',{method:'PATCH',body:{ssd_roots:roots,backend:$('#runtimeBackend').value,max_node_seconds:Number($('#maxNodeSeconds').value),max_upload_gib:Number($('#maxUploadGib').value)}});updateBackend();toast('Data and runtime settings saved');};modalClick('#saveDataSettings',saveData);modalClick('#scanNow',async()=>{await saveData();for(const root of state.settings.ssd_roots)await api('/assets/scan',{method:'POST',body:{root}});toast('SSD metadata scan started');pollDataProgress();});modalClick('#browseSsd',()=>browseSsd());modalClick('#saveCloudSettings',async()=>{state.settings=await api('/settings',{method:'PATCH',body:{s3_bucket:$('#s3Bucket').value.trim(),kms_key_arn:$('#kmsKey').value.trim(),batch_queue:$('#batchQueue').value.trim(),batch_job_definition:$('#batchDefinition').value.trim()}});toast('Cloud configuration saved');});modalClick('#cloudCheck',async()=>{$('#cloudCheckResult').textContent='Checking regional services…';const r=await api('/cloud/check',{method:'POST',body:{}});$('#cloudCheckResult').textContent=JSON.stringify(r,null,2);});modalClick('[data-cancel-transfer]',async(e,b)=>{await api('/transfers/'+b.dataset.cancelTransfer+'/cancel',{method:'POST',body:{}});toast('Transfer cancellation requested');});modalClick('#openTierAdmin',()=>state.user.role==='admin'?showAdmin():requestTier());modalClick('#saveRights',async()=>{const rights=$$('[data-rights]:checked').map(x=>x.dataset.rights);await api('/settings',{method:'PATCH',body:{rights_approved:rights}});toast('Rights approval snapshot recorded in audit');});$('#vaultProvider')?.addEventListener('change',e=>$('#vaultBindings').value=e.target.value);modalClick('#saveVault',async()=>{await api('/vault',{method:'POST',body:{provider:$('#vaultProvider').value,label:$('#vaultLabel').value,value:$('#vaultValue').value,bindings:$('#vaultBindings').value.split(',').map(x=>x.trim()).filter(Boolean)}});$('#vaultValue').value='';toast('Credential encrypted and stored');await showSettings('vault');});modalClick('[data-check-secret]',async(e,b)=>{const r=await api('/vault/'+b.dataset.checkSecret+'/check',{method:'POST',body:{}});toast(r.message,r.state==='rejected');});modalClick('[data-rotate-secret]',(e,b)=>{const s=state.vault.find(x=>x.id===b.dataset.rotateSecret);$('#vaultProvider').value=s.provider;$('#vaultLabel').value=s.label;$('#vaultBindings').value=s.bindings.join(',');$('#vaultValue').value='';$('#vaultValue').focus();});modalClick('[data-revoke-secret]',async(e,b)=>{await api('/vault/'+b.dataset.revokeSecret+'/revoke',{method:'POST',body:{}});toast('Platform binding revoked. Rotate/revoke the token at the provider as well.');showSettings('vault');});}
function updateBackend(){$('#backendLabel').innerHTML='<span class="status-dot"></span>'+({portable:'Portable research',docker:'Docker · isolated containers','aws-batch':'AWS Batch · us-east-1','hosted-demo':'Sample studio · AWS queue'}[state.settings.backend]||'Portable research');}
async function pollDataProgress(){clearTimeout(refreshTimer);await refreshAssets();if($('#scanProgress'))$('#scanProgress').textContent=state.scans.slice(0,3).map(s=>s.state+' · '+s.files+' files · '+bytes(s.bytes)+(s.error?' · '+s.error:'')).join('\n');if(state.library==='assets')renderLibrary();if(state.scans.some(s=>s.state==='running')||state.transfers.some(t=>['hashing','uploading'].includes(t.state)))refreshTimer=setTimeout(guarded(pollDataProgress),1000);else{toast('Data inventory refreshed · '+state.assets.length+' visible assets');renderInspector();}}
async function browseSsd(path=''){const r=await api('/directories?path='+encodeURIComponent(path));openModal('Browse external data',`<div class="mono note">${esc(r.path)}</div><button id="useDirectory" class="button primary">Register this directory</button>${r.parent?`<button id="parentDirectory" class="quiet">↑ Parent</button>`:''}<div style="margin-top:15px">${r.directories.map(d=>`<button class="outline-row" data-directory="${esc(d.path)}">▱ ${esc(d.name)}<span class="spacer"></span>›</button>`).join('')}</div>`,'LOCAL SSD');modalClick('[data-directory]',(e,b)=>browseSsd(b.dataset.directory));modalClick('#parentDirectory',()=>browseSsd(r.parent));modalClick('#useDirectory',async()=>{const s=await api('/settings');await api('/settings',{method:'PATCH',body:{ssd_roots:[...new Set([...s.ssd_roots,r.path])].slice(0,8)}});showSettings('data');});}
async function requestTier(){openModal('Request an entitlement review','<p>Tier changes in this deployment are reviewed by the workspace administrator.</p><div class="field"><label>Requested tier</label><select id="requestedTier"><option>academic</option><option>pro</option><option>enterprise</option></select></div><div class="field"><label>Institution and intended usage</label><textarea id="tierReason" rows="4"></textarea></div><button id="sendTierRequest" class="button primary">Submit review request</button>','TRUST CONTROL PLANE');modalClick('#sendTierRequest',async()=>{await api('/tier-requests',{method:'POST',body:{tier:$('#requestedTier').value,reason:$('#tierReason').value}});closeModal();toast('Review request recorded for the administrator');});}
async function resolveNodeImage(spec){if(state.user.role!=='admin')throw new Error('Image publication requires an administrator.');openModal('Resolve an execution image',`<p>Resolve the actual registry manifest, inspect its immutable digest, then approve it for this node. This step does not pull image layers or start compute.</p><div class="field"><label>OCI / BioContainer image</label><input id="imageReference" value="${esc(spec.image||'')}"></div><button id="resolveImage" class="button primary">Resolve manifest</button><div id="imageResult"></div>`,'RUNTIME PUBLICATION');modalClick('#resolveImage',async()=>{const r=await api('/tools/'+spec.id+'/resolve-image',{method:'POST',body:{image:$('#imageReference').value}});$('#imageResult').innerHTML=`<div class="note mono">${esc(r.image)}</div><p>${esc(r.source)}. Review code, database rights and the security profile before approval.</p><button id="approveImage" class="button primary">Approve this digest</button>`;modalClick('#approveImage',async()=>{const settings=await api('/settings');await api('/settings',{method:'PATCH',body:{image_approvals:{...settings.image_approvals,[spec.id]:r.image}}});toast('Immutable image approved and audited');closeModal();});});}
async function showAdmin(){const r=await api('/admin');openModal('Platform operations',`<div class="metric-grid" style="grid-template-columns:repeat(4,1fr)"><div class="metric"><strong>${r.runs.filter(x=>['running','queued','cancelling'].includes(x.state)).length}</strong><span>Active / queued runs</span></div><div class="metric"><strong>${r.users.length}</strong><span>Workspace accounts</span></div><div class="metric"><strong>${duration(r.users.reduce((a,u)=>a+u.reserved_seconds,0))}</strong><span>Reserved CPU</span></div><div class="metric"><strong>${bytes(r.storage_bytes)}</strong><span>Published artifact bytes</span></div></div><div class="settings-section"><div class="action-row"><h3>Emergency admission control</h3><span class="spacer"></span><button id="globalFreeze" class="button danger">Freeze & stop all pipelines</button><button id="globalUnfreeze" class="button quiet">Reopen admission</button></div><div class="field"><label>Audit reason for administrative actions</label><input id="adminReason" placeholder="Required · incident, quota review or approved request"></div></div><h3>Users & entitlements</h3><table class="table"><thead><tr><th>Account</th><th>Tier</th><th>CPU quota · hours</th><th>Used / reserved</th><th>Actions</th></tr></thead><tbody>${r.users.map(u=>`<tr><td>${esc(u.email)}<small style="display:block">${esc(u.role)} · ${u.frozen?'frozen':'active'}</small></td><td><select data-user-tier="${u.id}">${['trial','academic','pro','enterprise'].map(t=>`<option ${t===u.tier?'selected':''}>${t}</option>`).join('')}</select></td><td><input data-user-quota="${u.id}" type="number" min="0" value="${u.quota_seconds/3600}"></td><td>${duration(u.used_seconds)} / ${duration(u.reserved_seconds)}</td><td><button class="quiet" data-update-user="${u.id}">Save</button><button class="quiet danger" data-freeze-user="${u.id}" data-frozen="${u.frozen?'0':'1'}">${u.frozen?'Release':'Freeze'}</button></td></tr>`).join('')}</tbody></table><h3 style="margin-top:24px">Live pipeline monitor</h3>${r.runs.length?`<table class="table"><thead><tr><th>Run</th><th>State</th><th>Reserved / used</th><th>Action</th></tr></thead><tbody>${r.runs.slice(0,25).map(x=>`<tr><td class="mono">${esc(x.id.slice(-12))}</td><td class="state-${esc(x.state)}">${esc(x.state)}</td><td>${duration(x.reserved)} / ${duration(x.used)}</td><td>${['running','queued','cancelling'].includes(x.state)?`<button class="quiet danger" data-kill="${x.id}">Terminate</button>`:'Terminal'}</td></tr>`).join('')}</tbody></table>`:'<p>No executions have been submitted.</p>'}<div class="settings-section" style="margin-top:22px"><h3>Node quarantine</h3><div class="field-grid"><select id="quarantineTool">${state.nodes.map(n=>`<option value="${n.id}">${esc(n.name)}</option>`).join('')}</select><div class="action-row"><button id="quarantineNode" class="button danger">Quarantine</button><button id="releaseNode" class="button quiet">Release</button></div></div>${r.quarantine.map(q=>`<div class="note warning">${esc(q.tool_id)} · ${esc(q.reason)}</div>`).join('')}</div><h3>Audit chain · ${r.audit_verification.valid?'verified':'FAILED'}</h3><p>${r.audit_verification.records} records · independent WORM anchoring is a separate production control.</p><div class="mono note">${esc(r.audit_verification.head||'')}</div><table class="table"><thead><tr><th>Time</th><th>Action</th><th>Resource</th><th>Hash</th></tr></thead><tbody>${r.audit.slice(0,100).map(a=>`<tr><td class="audit-time">${new Date(a.event.time*1000).toLocaleString()}</td><td class="audit-action">${esc(a.event.action)}</td><td class="mono">${esc(a.event.resource.slice(-18))}</td><td class="mono">${a.hash.slice(0,16)}</td></tr>`).join('')}</tbody></table>`,'ADMIN · AUDITED OPERATIONS');const reason=()=>{const v=$('#adminReason').value.trim();if(v.length<5)throw new Error('Provide an audit reason first.');return v;};modalClick('[data-update-user]',async(e,b)=>{const id=b.dataset.updateUser;await api('/admin/users/'+id,{method:'POST',body:{reason:reason(),tier:$(`[data-user-tier="${id}"]`).value,quota_seconds:Math.round(Number($(`[data-user-quota="${id}"]`).value)*3600)}});toast('Entitlement override recorded');refreshSession();showAdmin();});modalClick('[data-freeze-user]',async(e,b)=>{await api('/admin/users/'+b.dataset.freezeUser,{method:'POST',body:{reason:reason(),frozen:b.dataset.frozen==='1'}});toast('Workspace freeze state updated');showAdmin();});modalClick('[data-kill]',async(e,b)=>{await api('/admin/runs/'+b.dataset.kill+'/kill',{method:'POST',body:{reason:reason()}});toast('Termination requested');showAdmin();});for(const [id,frozen]of [['globalFreeze',true],['globalUnfreeze',false]])modalClick('#'+id,async()=>{await api('/admin/freeze',{method:'POST',body:{frozen,reason:reason()}});toast(frozen?'Admission frozen; cancellation dispatched':'Admission reopened');showAdmin();});for(const[id,release]of [['quarantineNode',false],['releaseNode',true]])modalClick('#'+id,async()=>{await api('/admin/quarantine',{method:'POST',body:{tool_id:$('#quarantineTool').value,reason:reason(),release}});toast('Node release state updated');await loadCatalogue();showAdmin();});}
async function publishTool(){openModal('Bring your own tool.',`<p>Publish a digest-pinned container with explicit data contracts. It runs through the same resource, quota and governance checks. Publishing is restricted to the workspace owner in this deployment.</p><div class="settings-grid"><div class="field"><label>Tool name</label><input id="customName" placeholder="My validated analysis"></div><div class="field"><label>Code / asset rights</label><select id="customLicense"><option>FOSS</option><option>Academic</option><option>Commercial BYOL</option><option>Review required</option></select></div></div><div class="field"><label>Immutable OCI image</label><input id="customImage" placeholder="registry/repository@sha256:…"></div><div class="field"><label>Command · whitespace / quoted arguments</label><input id="customCommand" placeholder="samtools flagstat -O json {in.data}"><small>Use {in.data} for the input file and {work} for /work. Commands execute as argv, never a host shell. A tool must write its declared output file.</small></div><div class="settings-grid"><div class="field"><label>Input type</label><select id="customInput">${['ANY','FASTQ','BAM','SORTED_BAM','INDEXED_BAM','VCF','INDEXED_VCF','FASTA','BED','H5AD'].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label>Output type</label><select id="customOutput">${['REPORT','VCF','BAM','SORTED_BAM','INDEXED_BAM','FASTQ','BED','H5AD','ANY'].map(t=>`<option>${t}</option>`).join('')}</select></div></div><div class="field"><label>Output file · relative to /work</label><input id="customFile" placeholder="result.json"></div><div class="field"><label class="toggle-label">Capture stdout to the output file<input id="customStdout" type="checkbox" checked></label></div><div class="field"><label>Scoped BYOL licence file · optional</label><select id="customCredential"><option value="">No secret required</option><option>sentieon</option><option>dragen</option><option>hgmd</option><option>annovar</option></select><small>Use {secret.file} in the command. The credential must be explicitly bound to the published node in Vault. API keys stay in provider brokers.</small></div><button id="publishCustom" class="button primary">Publish reviewed tool contract</button>`,'UNIVERSAL CONTAINER');modalClick('#publishCustom',async()=>{const type=$('#customOutput').value;const r=await api('/tools/publish',{method:'POST',body:{name:$('#customName').value,image:$('#customImage').value,license:$('#customLicense').value,command_line:$('#customCommand').value,capture_stdout:$('#customStdout').checked,secret_delivery:$('#customCredential').value?{kind:'file',provider:$('#customCredential').value}:null,inputs:[{key:'data',type:$('#customInput').value}],outputs:[{key:'result',type}],output_files:{result:{file:$('#customFile').value,type}}}});await loadCatalogue();addNode(r.id);closeModal();toast('Tool contract published');});}
$('#settingsButton').onclick=guarded(()=>showSettings());$('#vaultButton').onclick=guarded(()=>showSettings('vault'));$('#tierButton').onclick=guarded(()=>showSettings('trust'));$('#adminButton').onclick=guarded(showAdmin);$('#publishButton').onclick=guarded(publishTool);$('#profileButton').onclick=guarded(()=>showSettings('general'));
$('#dataFile').onchange=guarded(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>64*1024*1024)throw new Error('Use SSD indexing or S3 sync for files larger than 64 MiB');await api('/uploads',{method:'POST',headers:{'X-File-Name':file.name,'Content-Type':'application/octet-stream'},body:file});await refreshAssets();state.library='assets';renderLibrary();e.target.value='';toast('File indexed in the workspace data store');});
let authSignup=false;function showAuth(setup=false){authSignup=setup;$('#authTitle').textContent=setup?'Your research workspace.':'Welcome back.';$('#authDescription').textContent=setup?'Create your research account. Explore includes bounded sample workflows; Research Pro requires a funded administrator allowance.':'Sign in to continue your pipelines, datasets and execution history.';$('#authSubmit').textContent=setup?'Create workspace':'Sign in';$('#authToggle').textContent=setup?'Already have an account? Sign in':'Create a research account';$('#authError').hidden=true;if(!$('#authModal').open)$('#authModal').showModal();}
$('#authModal').addEventListener('cancel',e=>e.preventDefault());$('#authToggle').onclick=()=>showAuth(!authSignup);$('#authForm').onsubmit=async e=>{e.preventDefault();$('#authSubmit').disabled=true;try{const f=new FormData(e.target),r=await api('/auth/'+(authSignup?'signup':'login'),{method:'POST',body:{email:f.get('email'),password:f.get('password'),otp:f.get('otp')||''}});state.user=r.user;state.csrf=r.csrf;$('#authModal').close();e.target.reset();await initialize();}catch(error){$('#authError').textContent=error.message;$('#authError').hidden=false;}finally{$('#authSubmit').disabled=false;}};
async function loadCatalogue(){const c=await api('/catalog');state.nodes=c.nodes;state.templates=c.templates;state.capabilities=c.capabilities;state.demo=c.demo;document.body.classList.toggle('hosted-demo',!!c.demo?.enabled);$('#sourceLink').hidden=!c.demo?.self_host_url;if(c.demo?.self_host_url)$('#sourceLink').href=c.demo.self_host_url;state.defs=new Map(c.nodes.map(n=>[n.id,n]));$('#catalogCount').textContent=c.nodes.length;renderCategories();renderLibrary();canvas.setGraph(state.graph,state.nodes);}
async function initialize(){await refreshSession();await loadCatalogue();state.settings=await api('/settings');document.body.classList.toggle('light',state.settings.theme==='light');updateBackend();await refreshAssets();const graphs=await api('/graphs');if(graphs.length){const g=await api('/graphs/'+graphs[0].id);if(g.body.nodes.every(n=>state.defs.has(n.tool)))replaceGraph(g.body,g.id,g.revision);else replaceGraph(state.templates[0].graph);}else replaceGraph(state.templates[0].graph);$('#connectionStatus').textContent='Workspace connected';renderBottom();if(location.pathname==='/settings')showSettings();if(location.pathname==='/admin'&&state.user.role==='admin')showAdmin();}
function resizer(el,axis,variable,min,max,direction=1){el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);const start=axis==='x'?e.clientX:e.clientY,original=parseFloat(getComputedStyle(document.body).getPropertyValue(variable));const move=e=>{const delta=((axis==='x'?e.clientX:e.clientY)-start)*direction;document.body.style.setProperty(variable,Math.max(min,Math.min(max,original+delta))+'px');};const stop=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',stop);};el.addEventListener('pointermove',move);el.addEventListener('pointerup',stop);});el.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const delta=['ArrowRight','ArrowDown'].includes(e.key)?15:-15,original=parseFloat(getComputedStyle(document.body).getPropertyValue(variable));document.body.style.setProperty(variable,Math.max(min,Math.min(max,original+delta*direction))+'px');});}
resizer($('#leftResize'),'x','--left',190,440);resizer($('#rightResize'),'x','--right',240,500,-1);resizer($('#bottomResize'),'y','--bottom',37,500,-1);let bottomCollapsed=false;$('#collapseBottom').onclick=()=>{bottomCollapsed=!bottomCollapsed;document.body.style.setProperty('--bottom',bottomCollapsed?'37px':'218px');$('#collapseBottom').textContent=bottomCollapsed?'⌃':'⌄';};
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)||$('#modal').open||$('#authModal').open)return;if(e.key==='/'){e.preventDefault();$('#librarySearch').focus();}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelection();}if((e.metaKey||e.ctrlKey)&&e.key==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.metaKey||e.ctrlKey)&&e.key==='s'){e.preventDefault();saveGraph();}if(e.key==='Escape')selectNode(null);if(e.key.toLowerCase()==='f')canvas.fit();if(state.selected&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const n=state.graph.nodes.find(n=>n.id===state.selected);remember();n.x+=e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0;n.y+=e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0;changed(false);}});
const extensions=installExtensions({api,state,esc,toast,guarded,openModal,closeModal,loadCatalogue,addNode,showSettings,showArtifact});
const bootstrap=await api('/bootstrap');state.demo=bootstrap.demo;document.body.classList.toggle('hosted-demo',!!bootstrap.demo?.enabled);if(bootstrap.user){state.user=bootstrap.user;state.csrf=bootstrap.csrf;await guarded(initialize)();}else showAuth(bootstrap.setup_required);
// Public diagnostics expose measurements, never credentials or patient data.
window.ngsDiagnostics={benchmark:()=>canvas.benchmark(),graphCounts:()=>({nodes:state.graph.nodes.length,edges:state.graph.edges.length}),version:'1.0.0'};

$('#mobileLibraryToggle').onclick=()=>document.body.classList.toggle('library-open');$('#mobileLibraryClose').onclick=()=>document.body.classList.remove('library-open');$('#mobileInspectorToggle').onclick=()=>document.body.classList.toggle('inspector-open');$('#mobileInspectorClose').onclick=()=>document.body.classList.remove('inspector-open');

async function pickAsset(node,key){
 openModal('Choose an indexed asset','<div class="search-wrap" style="margin:0 0 15px"><input id="assetPickerSearch" type="search" placeholder="Search 14k+ SSD files by name, family or format…" autofocus></div><div id="assetPickerResults"><p>Search by reference build, database name or format. At most 300 matching files are rendered.</p></div>','DATA BINDING');
 let timer;
 const search=async()=>{const term=$('#assetPickerSearch')?.value||'';const result=await api('/assets?q='+encodeURIComponent(term));const holder=$('#assetPickerResults');if(!holder)return;holder.innerHTML=result.assets.map(a=>`<button class="outline-row" data-pick-asset="${a.id}"><span>▱</span><span>${esc(a.name)}<small style="display:block">${esc(a.format)} · ${bytes(a.bytes)} · ${esc(a.assembly||a.family)}</small></span><span class="spacer"></span>＋</button>`).join('')||'<p>No matching indexed files.</p>';holder.querySelectorAll('[data-pick-asset]').forEach(b=>b.onclick=()=>{const a=result.assets.find(x=>x.id===b.dataset.pickAsset);remember();node.params[key]=a.id;if(node.tool==='reference.asset'&&a.assembly)node.params.assembly=a.assembly;if(!state.assets.some(x=>x.id===a.id))state.assets.push(a);changed(false);closeModal();toast('Asset bound without copying its contents');});};
 $('#assetPickerSearch').oninput=()=>{clearTimeout(timer);timer=setTimeout(guarded(search),220);};await search();$('#assetPickerSearch')?.focus();
}
